insert into public.email_automations(id,key,name,trigger_type,is_active) values('58f1f828-87ab-5673-a662-0d8507df9db0','course_month-love','Месяц любви','course',false) on conflict(id) do nothing;
insert into public.courses(slug,title,kind,landing_url,access_days,day_card_extra_days,webinar_extra_days,automation_id,source_hash) values('month-love','Месяц любви','practicum','https://zamkovoi.yoga/m4/',90,3,5,'58f1f828-87ab-5673-a662-0d8507df9db0','50ae36fb8cc857d4b97284b421a5dfd1a574526736510568202c2c906d57953d') on conflict(slug) do update set title=excluded.title,source_hash=excluded.source_hash;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('9ced276a-d690-585e-a584-c4549476cc04','58f1f828-87ab-5673-a662-0d8507df9db0','Урок 1',1,0,'{Месяц любви} Добро пожаловать!','{"ru":"{Месяц любви} Добро пожаловать!"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png" alt="Месяц любви" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я рад, что вы решились в течение месяца целенаправленно поработать с темой любви и отношений, а точнее с комплексом эмоциональных и телесных состояний, связанных с гармоничностью четвёртой чакры. Внимательно прочитайте это письмо, чтобы понимать, что вас ожидает.</p><p></p><p><strong>1. Расписание совместных практик</strong><br>Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке &quot;День&quot;. Чтобы его увидеть, при входе в Гармонизатор, укажите тот же ваш имейл, на который пришло данное письмо. Послезавтра вы получите второй урок - это будет наша первая совместная практика. Через неделю вам придёт вторая практика, ещё через неделю - третья, и через неделю - четвёртая. То есть в течение месяца, помимо вводного урока, вас ожидают четыре инереснейшие практики. Доступ к записям всех этих уроков сохранится у вас в течение трёх месяцев после окончания практикума. Тем не менее, я рекомендую вам проходить уроки не откладывая, так чтобы между практиками была неделя для внутренних трансформаций. Не увеличивайте интервалы между практиками, чтобы они не накапливались, как снежный ком. Наиболее эффективный темп занятий - одна практика в неделю. К тому-же имейте в виду, что первый урок посвящён тому, чтобы вы правильно сформулировали намерение на этот месяц, а также сами для себя определили небольшие дополнительные практики, которые будете выполнять каждый день в течение этого месяца.</p><p></p><p><strong>2. Техника безопасности</strong><br>Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу проконтролировать ваше состояние. Практикум ориентирован на людей со средним уровнем физической подготовки. Однако, у вам могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.</p><p></p><p><strong>3. Ответы на вопросы</strong><br>Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.</p><p></p><p><strong>4. Ваши регулярные действия - условие результатов</strong><br>Хотя это не программа подготовки космонавтов, всё-таки от вас потребуется некоторая дисциплина и целенаправленные действия. Так устроена эта жизнь, что для получения результатов нужно действовать. В том числе нужно действовать, если вы хотите наполнить жизнь тёплыми эмоциями и любовью... Так что поток уже поставлен. Это поток четвёртой чакры. Входите в этот поток и действуйте - выполняйте асаны, пранаяму, медитацию, а также те поведенческие практики, которые вы наметите для себя на первом уроке. И каждое своё действие совершайте, осознавая, что это ваша практика для гармонизации четвёртой чакры.</p><p></p><p><strong>5. Первый урок</strong><br>А теперь вы готовы перейти к первому уроку. В нём мы рассмотрим тему выработки здоровых привычек, и освоим технику суставной гимнастики, которую я рекомендую вам выполнять ежедневно в течение этого месяца. Урок довольно длинный, так как очень важно правильно сформулировать намерение и продумать небольшую практику на каждый день. Так как этот практикум я проводил в прямом эфире, вы услышите мои комментарии и ответы на задаваемые вопросы. Они помогут вам избежать распространённых ошибок.</p><p></p><p>Первый урок уже ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>Желаю вам плодотворного месяца!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png\" alt=\"Месяц любви\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я рад, что вы решились в течение месяца целенаправленно поработать с темой любви и отношений, а точнее с комплексом эмоциональных и телесных состояний, связанных с гармоничностью четвёртой чакры. Внимательно прочитайте это письмо, чтобы понимать, что вас ожидает.</p><p></p><p><strong>1. Расписание совместных практик</strong><br>Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке &quot;День&quot;. Чтобы его увидеть, при входе в Гармонизатор, укажите тот же ваш имейл, на который пришло данное письмо. Послезавтра вы получите второй урок - это будет наша первая совместная практика. Через неделю вам придёт вторая практика, ещё через неделю - третья, и через неделю - четвёртая. То есть в течение месяца, помимо вводного урока, вас ожидают четыре инереснейшие практики. Доступ к записям всех этих уроков сохранится у вас в течение трёх месяцев после окончания практикума. Тем не менее, я рекомендую вам проходить уроки не откладывая, так чтобы между практиками была неделя для внутренних трансформаций. Не увеличивайте интервалы между практиками, чтобы они не накапливались, как снежный ком. Наиболее эффективный темп занятий - одна практика в неделю. К тому-же имейте в виду, что первый урок посвящён тому, чтобы вы правильно сформулировали намерение на этот месяц, а также сами для себя определили небольшие дополнительные практики, которые будете выполнять каждый день в течение этого месяца.</p><p></p><p><strong>2. Техника безопасности</strong><br>Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу проконтролировать ваше состояние. Практикум ориентирован на людей со средним уровнем физической подготовки. Однако, у вам могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.</p><p></p><p><strong>3. Ответы на вопросы</strong><br>Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.</p><p></p><p><strong>4. Ваши регулярные действия - условие результатов</strong><br>Хотя это не программа подготовки космонавтов, всё-таки от вас потребуется некоторая дисциплина и целенаправленные действия. Так устроена эта жизнь, что для получения результатов нужно действовать. В том числе нужно действовать, если вы хотите наполнить жизнь тёплыми эмоциями и любовью... Так что поток уже поставлен. Это поток четвёртой чакры. Входите в этот поток и действуйте - выполняйте асаны, пранаяму, медитацию, а также те поведенческие практики, которые вы наметите для себя на первом уроке. И каждое своё действие совершайте, осознавая, что это ваша практика для гармонизации четвёртой чакры.</p><p></p><p><strong>5. Первый урок</strong><br>А теперь вы готовы перейти к первому уроку. В нём мы рассмотрим тему выработки здоровых привычек, и освоим технику суставной гимнастики, которую я рекомендую вам выполнять ежедневно в течение этого месяца. Урок довольно длинный, так как очень важно правильно сформулировать намерение и продумать небольшую практику на каждый день. Так как этот практикум я проводил в прямом эфире, вы услышите мои комментарии и ответы на задаваемые вопросы. Они помогут вам избежать распространённых ошибок.</p><p></p><p>Первый урок уже ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>Желаю вам плодотворного месяца!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-love-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png","alt":"